create or replace function public.sales_charge_catalog_insert_v610(p_tenant_id uuid,p_location_id uuid,p_device_id uuid,p_code text,p_name text,p_service_variant_id uuid) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_id uuid; begin perform private.erp_validate_vertical_device_scope(p_tenant_id,p_location_id,p_device_id,'restaurant','operate'); if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if; if not(private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'restaurant.manage') or private.erp_has_permission(p_tenant_id,'sales.manage')) then raise exception 'Manage permission required'; end if; perform private.sales_charge_catalog_assert_v610(p_tenant_id,p_service_variant_id); insert into public.sales_charge_catalog_v610(tenant_id,code,name,service_variant_id) values(p_tenant_id,upper(trim(p_code)),trim(p_name),p_service_variant_id) returning id into v_id; return v_id; end; $$;;
